// Seeding always targets version 1 of each exam; it never touches version 2+
// created later via the admin UI's generate/import flow.
async function main() {
  for (const exam of EXAMS) {
    if (exam.questions.length < 20) {
      throw new Error(`Exam ${exam.slug} has only ${exam.questions.length} questions (minimum 20 required)`);
    }

    const quiz = await prisma.quiz.upsert({
      where: { slug: exam.slug },
      update: {
        ministere: exam.ministere,
        ministereFr: exam.ministereFr,
        ministereAr: exam.ministereAr,
        corpsFr: exam.corpsFr,
        corpsAr: exam.corpsAr,
        titleFr: examTitle(exam.corpsFr),
        titleAr: examTitleAr(exam.corpsAr),
        descriptionFr: examDesc(exam.corpsFr, exam.questions.length),
        descriptionAr: examDescAr(exam.corpsAr, exam.questions.length),
        questionsPerAttempt: exam.questions.length,
      },
      create: {
        slug: exam.slug,
        ministere: exam.ministere,
        ministereFr: exam.ministereFr,
        ministereAr: exam.ministereAr,
        corpsFr: exam.corpsFr,
        corpsAr: exam.corpsAr,
        titleFr: examTitle(exam.corpsFr),
        titleAr: examTitleAr(exam.corpsAr),
        descriptionFr: examDesc(exam.corpsFr, exam.questions.length),
        descriptionAr: examDescAr(exam.corpsAr, exam.questions.length),
        questionsPerAttempt: exam.questions.length,
      },
    });

    const version = await prisma.quizVersion.upsert({
      where: { quizId_versionNumber: { quizId: quiz.id, versionNumber: 1 } },
      update: { questionsPerAttempt: exam.questions.length },
      create: { quizId: quiz.id, versionNumber: 1, questionsPerAttempt: exam.questions.length },
    });

    await prisma.question.deleteMany({ where: { quizVersionId: version.id } });

    for (let i = 0; i < exam.questions.length; i++) {
      const q = exam.questions[i];
      await prisma.question.create({
        data: {
          quizVersionId: version.id,
          textFr: q.textFr,
          textAr: q.textAr,
          choicesFr: JSON.stringify(q.choicesFr),
          choicesAr: JSON.stringify(q.choicesAr),
          correctIndices: JSON.stringify(q.correctIndices),
          explanationFr: q.explanationFr,
          explanationAr: q.explanationAr,
          order: i,
        },
      });
    }

    console.log(`Seeded ${exam.slug} (version 1) with ${exam.questions.length} questions`);
  }

  console.log("Seed terminé avec succès.");
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
